-- 傾印  資料表 cooookie.admin_roles 結構
CREATE TABLE IF NOT EXISTS `admin_roles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT '角色名稱',
  `description` varchar(255) DEFAULT NULL COMMENT '描述',
  `permissions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '權限列表' CHECK (json_valid(`permissions`)),
  `is_systemX` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否為系統保留(超級管理員)',
  `is_developerX` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否為開發人員(上帝視角)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

